public interface PaymentStrategy {
    void pay(double amount);
}

public class CreditCardPayment implements PaymentStrategy {
    private final String cardNumber;
    public CreditCardPayment(String cardNumber) {
        this.cardNumber = cardNumber;
    }
    @Override
    public void pay(double amount) {
        System.out.println("Paid $" + amount + " via Card " + cardNumber);
    }
}

public class UpiPayment implements PaymentStrategy {
    private final String upiId;
    public UpiPayment(String upiId) {
        this.upiId = upiId;
    }
    @Override
    public void pay(double amount) {
        System.out.println("Paid $" + amount + " via UPI ID " + upiId);
    }
}

public class ShoppingCart {
    private PaymentStrategy strategy;
    public void setStrategy(PaymentStrategy strategy) {
        this.strategy = strategy;
    }
    public void checkout(double amount) {
        strategy.pay(amount);
    }
}

import java.util.*;

public interface Observer {
    void update(String event);
}

public class Subject {
    private final List<Observer> observers = new ArrayList<>();
    public void attach(Observer o) { observers.add(o); }
    public void detach(Observer o) { observers.remove(o); }
    public void notifyAllObservers(String event) {
        for (Observer o : observers) {
            o.update(event);
        }
    }
}

public class EmailNotification implements Observer {
    @Override
    public void update(String event) {
        System.out.println("Email alert sent: " + event);
    }
}

public interface State {
    void handleRequest(Context ctx);
}

public class Context {
    private State state;
    public Context(State state) { this.state = state; }
    public void setState(State state) { this.state = state; }
    public void request() { state.handleRequest(this); }
}

public class OffState implements State {
    @Override
    public void handleRequest(Context ctx) {
        System.out.println("Turning ON...");
        ctx.setState(new OnState());
    }
}

public class OnState implements State {
    @Override
    public void handleRequest(Context ctx) {
        System.out.println("Turning OFF...");
        ctx.setState(new OffState());
    }
}

