public class DatabaseConnection {
    private static volatile DatabaseConnection instance;
    private DatabaseConnection() {}

    public static DatabaseConnection getInstance() {
        if (instance == null) {
            synchronized (DatabaseConnection.class) {
                if (instance == null) {
                    instance = new DatabaseConnection();
                }
            }
        }
        return instance;
    }
}

public class HttpRequest {
    private final String url;
    private final String method;
    private final int timeout;

    private HttpRequest(Builder b) {
        this.url = b.url;
        this.method = b.method;
        this.timeout = b.timeout;
    }

    public static class Builder {
        private String url;
        private String method = "GET";
        private int timeout = 5000;

        public Builder url(String url) { this.url = url; return this; }
        public Builder method(String method) { this.method = method; return this; }
        public Builder timeout(int ms) { this.timeout = ms; return this; }
        public HttpRequest build() { return new HttpRequest(this); }
    }
}

public interface Coffee {
    double cost();
    String description();
}

public class SimpleCoffee implements Coffee {
    public double cost() { return 2.0; }
    public String description() { return "Simple Coffee"; }
}

public abstract class CoffeeDecorator implements Coffee {
    protected final Coffee decorated;
    public CoffeeDecorator(Coffee c) { this.decorated = c; }
    public double cost() { return decorated.cost(); }
    public String description() { return decorated.description(); }
}

public class Milk extends CoffeeDecorator {
    public Milk(Coffee c) { super(c); }
    public double cost() { return super.cost() + 0.5; }
    public String description() { return super.description() + ", Milk"; }
}

public interface Command {
    void execute();
    void undo();
}

public class Light {
    public void turnOn() { System.out.println("Light ON"); }
    public void turnOff() { System.out.println("Light OFF"); }
}

public class TurnOnLightCommand implements Command {
    private final Light light;
    public TurnOnLightCommand(Light l) { this.light = l; }
    public void execute() { light.turnOn(); }
    public void undo() { light.turnOff(); }
}

public class RemoteInvoker {
    private Command cmd;
    public void setCommand(Command c) { this.cmd = c; }
    public void click() { cmd.execute(); }
}
